    for line in text:
        for s in severities:
            # count exact uppercase token occurrences as event severity
            if s in line:
                file_counts[s] += 1
    for s in severities:
        counts['total'][s] += file_counts[s]
    for period, (start, end) in ranges.items():
        if start <= fdate <= end:
            for s in severities:
                counts[period][s] += file_counts[s]

out = Path('/app/summary.csv')
with out.open('w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['period', 'severity', 'count'])
    for p in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
        for s in severities:
            w.writerow([p, s, counts[p][s]])

print('WROTE', out)
for p in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    print(p, counts[p])
